'use strict';
let guidedDemo=null;
async function loadGuidedDemo(){try{const r=await fetch('./assets/demo-statebench.json');if(r.ok)guidedDemo=await r.json();}catch{}}
function demoTeaser(){return `<section class="demo-invitation"><div><span class="badge">מתחילים כאן</span><h2>איך כתבה הופכת לפוסט?</h2><p>דוגמה אמיתית, צעד אחר צעד: מקור, בחירה, כתיבה, ביקורת ותמונה.</p></div><button class="button" data-action="demo">לצפייה בדוגמה המלאה ←</button></section>`;}
function renderDemo(){if(!guidedDemo)return heading('הדוגמה לא נטענה','נסו לרענן. העבודה האישית שלכם לא השתנתה.');const d=guidedDemo;return heading('מהכתבה לפוסט — דוגמה מלאה','עוברים על התהליך, רואים מה תוקן ופותחים עותק משלכם לעריכה.',`<button class="button ghost" data-action="home">חזרה לשולחן העבודה</button>`)+`
<div class="demo-layout"><nav class="demo-nav" aria-label="שלבי הדוגמה">${['המקור','הרעיון','טיוטה וביקורת','הפוסט והתמונה','עכשיו תורכם'].map((x,i)=>`<button data-action="demo-step" data-step="${i+1}"><span aria-hidden="true">${i+1}</span>${x}</button>`).join('')}</nav><div class="demo-content">
<section class="demo-panel" id="demo-step-1" tabindex="-1"><p class="eyebrow">שלב 1 · חוקר המקורות</p><h2>מתחילים מכתבה שקראנו</h2><p><a href="${esc(safeURL(d.evidence.source.url))}" target="_blank" rel="noopener noreferrer">${esc(d.evidence.source.title)} ↗</a></p><p class="muted">Ai2 · פורסם ב־3.11.2026 · אותר בסריקת המקורות של 4.11.2026</p><p>נבחר פריט מדוח ה־RSS, ואז נקרא גוף הכתבה. קריאת המקור שימשה בסיס לטענות — הכותרת לבדה לא הספיקה.</p><div class="demo-note">הדגמה מתועדת שנכתבה בסשן עוזר. אינה הרצה יומית אוטונומית. הממצאים מיוחסים לחוקרים; לא הרצנו את המחקר בעצמנו.</div><details><summary>מה נשמר כראיה?</summary>${d.evidence.claims.map(c=>`<p><strong>${esc(c.id)} · ${esc(c.statement)}</strong><br><span class="muted">${esc(c.locator)}</span><br><q lang="en" dir="ltr">${esc(c.evidence_excerpt)}</q></p>`).join('')}<p class="muted">נשמרו קטעים קצרים והפניה למקור, ולא העתק מלא של הכתבה.</p></details></section>
<section class="demo-panel" id="demo-step-2" tabindex="-1"><p class="eyebrow">שלב 2 · העורך והכותב</p><h2>בוחרים משהו שהקהילה תוכל להבין</h2><p>במקום סקירה טכנית, נבחרה המחשה מחיי היום־יום: מה נשאר בתוקף כשהיום והשעה של פגישה משתנים?</p><div class="demo-note"><strong>מטרת הפוסט:</strong> להזמין את הקוראים לבדוק את הסיכום מול הפרטים שנתנו, בעזרת דוגמה קטנה שאפשר להבין מיד.</div><details><summary>מה הייתה הנחיית הכתיבה?</summary><pre class="demo-text">${esc(d.brief)}</pre></details><p class="muted">העברית שיחתית וברורה. הקול האישי של עמית עדיין זמני, עד קבלת דוגמאות ואישור.</p></section>
<section class="demo-panel" id="demo-step-3" tabindex="-1"><p class="eyebrow">שלב 3 · מבקר התוכן</p><h2>הטיוטה הראשונה לא הייתה סוף העבודה</h2><details><summary>קריאת הטיוטה הראשונה</summary><pre class="demo-text">${esc(d.v1)}</pre></details><p>סאב־אייג׳נט ביקורת קרא את הטיוטה ואת הראיות. אלה התיקונים שנעשו בעקבותיו:</p><ul class="demo-changes">${d.corrections.map(x=>`<li><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></li>`).join('')}</ul><details><summary>דוח הביקורת המלא</summary><pre class="demo-text">${esc(d.review)}</pre></details><details><summary>בדיקת הגרסה המתוקנת</summary><pre class="demo-text">${esc(d.finalReview)}</pre></details><p class="muted">המבקר הסתמך על חבילת הראיות, ולא ביצע מחקר עצמאי. הגרסה הראשונה נשמרה לצד התיקון.</p></section>
<section class="demo-panel" id="demo-step-4" tabindex="-1"><p class="eyebrow">שלב 4 · התוצר</p><h2>הפוסט המתוקן והתמונה המצורפת</h2><div class="badges">${badge('גרסה 2')}${badge('ממתינה לאישור עמית','yellow')}</div><div class="demo-result"><div><pre class="demo-text demo-post" id="demo-post-text">${esc(d.v2)}</pre><div class="demo-buttons"><button class="button" data-action="demo-copy">העתקת הפוסט</button><a class="button ghost" href="./assets/statebench-post.md" download>הורדת הטקסט</a></div></div><figure><img class="demo-image" src="./assets/statebench-image.png" alt="${esc(d.imageAlt)}" width="1080" height="1350"><figcaption>כרטיס הסבר מקורי · 1080×1350</figcaption><a class="button ghost" href="./assets/statebench-image.png" download>הורדת התמונה</a></figure></div><details><summary>איך בודקים את הטענות בפוסט?</summary>${d.mappings.map(m=>`<p><strong>${esc(m.claim_id)}</strong> · ${esc(m.sentence)}</p>`).join('')}<p>התרגיל והצעת העבודה הם המחשות מקוריות. הם אינם תוצאת ניסוי או המלצה שנבדקה במחקר.</p></details></section>
<section class="demo-panel" id="demo-step-5" tabindex="-1"><p class="eyebrow">שלב 5 · העבודה שלכם</p><h2>פותחים עותק ומשנים אותו</h2><p>לחצו לפתיחת עותק בעורך הרגיל. תוכלו לשנות ניסוח, לראות את המקור, להשוות גרסאות ולתעד ביקורת. הדוגמה המקורית תישאר כאן.</p><button class="button" data-action="demo-edit">פתיחת עותק לעריכה ←</button><p class="muted">העותק נשמר בדפדפן הזה. שינויים בפוסט דורשים ביקורת ואישור חדשים. הטקסט והתמונה לא פורסמו לקהילה.</p><div class="demo-note"><strong>מה הושלם כאן?</strong> בחירת מקור, קריאה, כתיבה, ביקורת, תיקון ותוצר להורדה. אישור הפרסום נשאר שלכם. הדוגמה אינה מפעילה את סריקת הבוקר או מחולל טיוטות אוטונומי.</div></section>
</div></div>`;}
function editGuidedDemo(){if(!guidedDemo)throw Error('הדוגמה עדיין לא זמינה.');const existing=state.drafts.find(x=>x.id==='statebench-demo-draft');if(existing){go('editor',existing.id);return;}if(state.sources.length>=100||state.drafts.length>=200)throw Error('מגבלת סביבת העבודה הושגה. הורידו גיבוי.');const d=guidedDemo,t=stamp();state.sources.unshift({id:'statebench-demo-source',title:'StateBench · ראיות נבחרות מהכתבה',url:d.evidence.source.url,content:d.evidence.claims.map(c=>c.evidence_excerpt).join('\n'),claim:d.evidence.claims.map(c=>c.statement).join(' '),excerpt:d.evidence.claims[0].evidence_excerpt,verified:true,basis:'full_text',coverage:'selected_excerpts',createdAt:t,publishedAt:'2026-11-03'});state.drafts.unshift({id:'statebench-demo-draft',sourceId:'statebench-demo-source',title:'מה נשאר בתוקף בשיחה עם AI?',text:d.v2,version:2,origin:'assistant_session',visual:{title:'מה השתנה בדרך?',points:['התחלה: שני, 10:00.','השעה השתנתה: שני, 12:00.','היום השתנה: שלישי, 12:00.']},history:[{version:1,title:'מידע משתנה בשיחה',text:d.v1,at:t}],review:{version:2,type:'ai_session',reviewer:'סקירת שילוב אחרי ביקורת הסאב־אייג׳נט',findings:d.corrections.map(x=>x.title+' · '+x.detail),scores:{accuracy:4,clarity:4,usefulness:4,voice:3},blocking:false},approvedVersion:null,createdAt:t,updatedAt:t});commit('נפתח עותק לדוגמה. העבודה הקודמת שלכם נשמרה.');go('editor','statebench-demo-draft');}
